class Solution:
    def reformatNumber(self, number: str) -> str:
        d = number.replace('-', '').replace(' ', '')
        blocks = []
        while len(d) > 4:
            blocks.append(d[:3])
            d = d[3:]
        if len(d) == 4:
            blocks.append(d[:2])
            blocks.append(d[2:])
        elif d:
            blocks.append(d)
        return '-'.join(blocks)

