class Solution {
public:
    string reformatNumber(string number) {
        string d;
        for (char c : number)
            if (isdigit(c)) d += c;
        vector<string> blocks;
        int i = 0, n = d.size();
        while (n - i > 4) {
            blocks.push_back(d.substr(i, 3));
            i += 3;
        }
        if (n - i == 4) {
            blocks.push_back(d.substr(i, 2));
            blocks.push_back(d.substr(i + 2, 2));
        } else if (i < n) {
            blocks.push_back(d.substr(i));
        }
        string res;
        for (int j = 0; j < (int)blocks.size(); j++) {
            if (j) res += '-';
            res += blocks[j];
        }
        return res;
    }
};

