var reformatNumber = function(number) {
    let d = number.replace(/[^0-9]/g, '');
    const blocks = [];
    while (d.length > 4) {
        blocks.push(d.slice(0, 3));
        d = d.slice(3);
    }
    if (d.length === 4) {
        blocks.push(d.slice(0, 2), d.slice(2));
    } else if (d.length) {
        blocks.push(d);
    }
    return blocks.join('-');
};

