class Solution:
    def reformatNumber(self, number: str) -> str:
        digits = [c for c in number if c.isdigit()]
        total = len(digits)
        special = total % 3 == 1
        res = []
        for p, c in enumerate(digits, 1):
            res.append(c)
            if p == total:
                break
            if special:
                if (p % 3 == 0 and p <= total - 4) or p == total - 2:
                    res.append('-')
            elif p % 3 == 0:
                res.append('-')
        return ''.join(res)

