            if (isdigit(c)) digits += c;
        int total = digits.size();
        bool special = total % 3 == 1;
        string res;
        for (int p = 1; p <= total; p++) {
            res += digits[p - 1];
            if (p == total) break;
            bool dash = special ? ((p % 3 == 0 && p <= total - 4) || p == total - 2)
                                : (p % 3 == 0);
            if (dash) res += '-';
        }
        return res;
    }
};

