            if (Character.isDigit(c)) buf.append(c);
        String digits = buf.toString();
        int total = digits.length();
        boolean special = total % 3 == 1;
        StringBuilder res = new StringBuilder();
        for (int p = 1; p <= total; p++) {
            res.append(digits.charAt(p - 1));
            if (p == total) break;
            boolean dash = special
