var reformatNumber = function(number) {
    const digits = [...number].filter((c) => c >= '0' && c <= '9');
    const total = digits.length;
    const special = total % 3 === 1;
    let res = '';
    for (let p = 1; p <= total; p++) {
        res += digits[p - 1];
        if (p === total) break;
        const dash = special
            ? (p % 3 === 0 && p <= total - 4) || p === total - 2
            : p % 3 === 0;
        if (dash) res += '-';
    }
    return res;
};
